INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(1, 'ruRU', 'Вот банка с пеплом. Это пепел моего рассудка, моей страсти и моей целеустремлённости. Всё было уничтожено ими самими. Пусть все, кто взглянет на эти опустошённые земли Адского Пламени, вспомнят этого павшего пеона. Он проливал кровь за Альянс и жертвовал собой за Орду лишь для того, чтобы быть доведённым до безумия злобными и бездушными тварями, пожравшими всё, что было ему дорого. Пока они пируют плодами его труда, пусть познают его гнев. Может, не в этом мире, но в каждом мире после него. Это моё заявление, моя торжественная клятва и моё вечное обещание. Я отомщу за свои страдания.', 12340),
(2, 'ruRU', 'С тех пор как ты покинул Вечную Рощу, я продолжил изучение Книги Ворона и обнаружил сведения, которые помогут тебе одолеть бога воронов.$BОсвобождение духов связало их с тобой, так что я ожидаю, что они охотно предложат свою помощь в битве против бога воронов.$BКогда ты впервые освободишь духов, они будут дремать, как делали это на протяжении столетий. Используя заклинания исцеления со временем, ты сможешь наполнить их энергией, пробуждая к жизни и получая их помощь в бою. Когда магия рассеется, они снова погрузятся в сон.$BДалее следует собрание моих заметок о каждом духе птицы:', 12340),
(3, 'ruRU', 'Дух сокола$BДух сокола наделён невероятной скоростью и ловкостью, высоко почитаемый аракоа за острые охотничьи навыки. Он одарит тебя частью своей скорости в сотворении заклинаний и ближнем бою, если ты наполнишь его энергией заклинанием исцеления со временем.', 12340),
(4, 'ruRU', 'Дух орла$BПо традиции аракоа, дух орла не был столь быстр, как его брат-сокол, но обладал величайшим мастерством в охоте. Дух орла обратит своё мастерство против твоих врагов, если ты пробудишь его от сна заклинанием исцеления со временем.', 12340),
(5, 'ruRU', 'Дух ястреба$B$BНа табличке ястреб упоминается с большим почтением, словно он когда-то был в союзе с вороном. Древний символ аракоа, означающий возмездие, дух ястреба часто призывался жертвами несправедливости. Пробуждение духа заклинанием исцеления со временем позволит тебе разделить его силу, нанося урон тем, кто причиняет тебе вред.', 12340),
(27, 'ruRU', 'Дорогой Уильям, прошло много лет с тех пор, как мы говорили, но я верю, что ты и твой брат в порядке, и что твоя аптека процветает. Я должен попросить тебя об одолжении, Уильям. Короче говоря, мой внук Томми Джо отдал своё сердце юной Мейбелл Маклюр. И хотя они обожают друг друга... наши семьи, что ж, наши семьи враждуют уже много лет.', 0),
(37, 'ruRU', 'Достопочтенный магистрат Соломон: я скорблю вместе с вами о погибших. Я лично прослежу, чтобы Король узнал о ситуации, и искренне надеюсь, что смогу привести подкрепление в Озёрный край. Его Величество последнее время появляется редко и ведёт себя довольно странно. Я делюсь этим с вами по секрету. До встречи, Генерал Маркус Джонатан Королевство Штормграда', 0),
(40, 'ruRU', 'У них построена огромная подземная сеть. Больше, чем ты думаешь, Стаутмантл. От Пиратской Бухты до самой крепости Штормграда. Можешь быть храбрым паладином, но ты глупец, если думаешь, что сможешь их остановить. Они работают над оружием массового поражения. В конце концов, если каменщики что-то и умеют, так это строить по-крупному. Ты ведь не думал, что всё дело в тыквенных фермах и виноградниках, не так ли? Я отплатил тебе за услугу. Теперь оставь меня в покое! --В', 0),
(44, 'ruRU', 'Зная Эдвина ВанКлифа лично всю свою жизнь, могу сказать, что противостоять ему как врагу — непростая задача. Видишь ли, он был моим другом детства, и я лично обучал его искусству теней, думая, что однажды он захочет работать рядом со мной. Если ВанКлиф стоит во главе Братства Теней, пусть Свет помилует наши души. Мастер Матиас Шо Гильдия ассасинов Штормграда', 0),
(57, 'ruRU', '[Слова ниже были второпях нацарапаны на обратной стороне документа] Мы надавили на Фарлбро и получили его документ. Подумали, может, тебе пригодится, если захочешь выправить такой же на своё место. Фарлбро не доставят проблем. В последний раз, когда я их видел, они покидали Западный край со сломанной повозкой.', 0),
(61, 'ruRU', 'И когда наши братья уходят В миры за пределами известного Душа-дух твердеет Глубоко под Долиной. И когда наши братья уходят В Храм Горы Мы будем хранить их вечный дух Заключённый в священном синем кристалле. И когда наши братья уходят Луна над Долиной светит.', 0),
(77, 'ruRU', 'ДЕНЬ ПЕРВЫЙ Ученик и я сегодня прибыли в Стылую долину. Путь через пещеру прошёл в основном без происшествий. Мы разбили лагерь на хорошем расстоянии от пещеры, где, как нам сказали, собрались тролли. ДЕНЬ ВТОРОЙ Проклятый волчий вой почти не давал спать всю ночь. Через несколько дней у меня будет новая одежда из волчьей шкуры. Паренёк сегодня сцепился с троггом, подрался, и', 0),
(97, 'ruRU', 'Зелёные холмы Тернистой долины Наш первый день прошёл так хорошо, как только можно было ожидать от первых дней. Большую часть времени мы занимались необходимыми приготовлениями для устройства базового лагеря. Я нашёл подходящее место у пресноводного речного залива. Судя по старым, заброшенным докам рядом, это место было обитаемо когда-то раньше. Что же до первоначальных обитателей — об этом может рассказать только время.', 0),
(99, 'ruRU', 'В последующие годы, после того как Штормград предал Гильдию Каменщиков, сэр Эрлгадин стал горько относиться к роли дворян в Королевстве. Он больше не хотел занимать положение, которое кровная линия его отца заслужила для него в Палате Дворян. Но я отвлекаюсь. Цель этого рассказа — не политический трактат и не биография. Это повествование о моём опыте охоты на крупную дичь в зелёных холмах Тернистой долины.', 0),
(101, 'ruRU', 'Как раз когда я собирался спросить у Аджек о её безразличии к сегодняшней охотничьей стратегии, она потянулась за колчаном, выхватила стрелу и выпустила выстрел прямо в сторону бедного Барнила. Но целью Аджек был не Барнил. Ведь когда Барнил отступил в сторону с открытым ртом, на поверхность всплыл крупный речной крокольв со стрелой Аджек, идеально вонзившейся между его двумя большими глазами.', 0),
(103, 'ruRU', 'Во время одной такой оговорки Эрлгадин тяжело положил руку на плечо Барнила. Аджек и я бросили беглый взгляд, полагая, что мужчина просто давал Барнилу давно заслуженный выговор за его неосторожность. Эрлгадин, однако, медленно повёл головой в сторону соседнего поваленного дерева. Глядя на нас оттуда, были два пронзительных чёрных глаза прямо над пастью, полной острых как бритва клыков.', 0),
(107, 'ruRU', 'На скалистом утёсе наверху, силуэтом на фоне заходящего солнца, я разглядел крупнейшего хищного кота, какого я когда-либо видел. Мне удалось сделать один неуклюжий выстрел из ружья, но кот не сдвинулся с места. Он зарычал снова, на этот раз громче первого, и исчез. Мы собрали свои вещи и мрачно направились обратно в лагерь.', 0),
(109, 'ruRU', 'В этот день мы отправились на юг, следуя по свежим следам пантеры. Вскоре мы достигли ущелья, через которое был перекинут огромный веревочный мост. Я не мог не вспомнить описательные записи Бранна об этом регионе, глядя на это инженерное чудо. Так часто считалось, что местные тролли — примитивная и неучёная раса, но, глядя на мастерство создания этого моста, я смог оценить умение, с которым троллийские строители преодолели, казалось бы, невозможную задачу.', 0),
(111, 'ruRU', 'Аджек и сэр Эрлгадин оба стояли готовые, ружья направлены на вздымающиеся заросли у основания раскачивающихся деревьев. Полуденное солнце нещадно палило нас. Медленная струйка пота стекала со лба Эрлгадина, когда он оттянул курок. При звуке щелчка плотная листва раздвинулась, и большая чёрная пантера — прекрасный экземпляр — выскочила на равнину.', 0),
(113, 'ruRU', 'Его ружьё резко дёрнулось назад в его руках. Ствол качнулся в сторону и поднялся прямо под ружьё Аджек. Аджек выбрала именно этот момент, чтобы нажать на курок. Ружьё, с прицелом, теперь неуклюже сбитым в сторону линии деревьев, выстрелило с отчётливым грохотом. Стая птиц вырвалась с криком из кроны, разлетаясь во все стороны. Облако дыма поднялось от дерева. Мы в изумлении наблюдали, как огромная ветвь упала прямо на убегающую пантеру, переломив ей хребет.', 0),
(117, 'ruRU', 'Я стоял перед возвышающимся инферналом на поле боя, когда армия Пылающего Легиона наступала со всех сторон. Буйная банда троллей кажется безобиднее зайца на холмах Дун Морога. Мы прошли мимо руин Ткаши без происшествий, к большому облегчению Барнила. Отряд продолжил двигаться на запад, к Великому морю, обходя руины Зул''Кунды с юга. Когда мы поднялись на высокие морские утёсы, мы увидели нашего первого раптора.', 0),
(149, 'ruRU', 'же вы найдёте то, что необходимо для моего заклинания призыва великого Циклониана. Пусть удача сопутствует вам.\n\n--Бат''ра Дозорный Ветра\n\n', 12340),
(152, 'ruRU', 'Аджек и сэр Эрлгадин приготовили оружие, прикрывая меня с обеих сторон, спинами к морю. Барнил испустил смирённый вздох и достал топор. Хлёсткохвосты были уже почти рядом. Их уверенная походка замедлилась. Теперь они выслеживали свою жертву, зная, что та в ловушке.', 0),
(204, 'ruRU', 'Я не могу описать, что случилось дальше. Это ясно в моей памяти, но даже моя несчастная душа не может перенести на бумагу события тех нескольких ужасных минут. Я могу лишь написать, что семья Свена была убита. И вскоре после этого Свен вернулся на эту мрачную, смертельную сцену. Такое горе было в нём, что я боялся показаться. И настолько я боялся, что он найдёт меня, что я бежал из своего укрытия в сарае. Я не знаю, где сейчас Свен, но молюсь, что однажды он обретёт покой.', 0),
(217, 'ruRU', 'Дорогая Иветта, я доверю это письмо нашему самому быстрому гонцу. Молюсь, чтобы он нашёл путь через силы, окружающие нас. И молюсь, чтобы ты прочла эти слова, ибо это последнее, что ты услышишь от меня. Единственное утешение в эти тёмные дни — облегчение, которое я чувствую, зная, что ты свободна от моей судьбы.', 0),
(228, 'ruRU', 'следует собрать сведения об организации нежити в Брилле. Капитан Вашон, похоже, усиливается активность нежити у северной башни. С этим вторжением нужно разобраться быстро и решительно. Капитан Мелроуз, есть опасения насчёт уровня организации нежити у границ Чумных земель. Новая группа людей будет направлена на вашу позицию в ближайшие недели. Слава Свету', 0),
(243, 'ruRU', 'Пытаясь собрать образцы мха, я наткнулся на сцену кровавой битвы. Племя Мерзкого Плавника мурлоков подверглось нападению банды гноллов-налётчиков. На поле боя валялись трупы и гноллов, и мурлоков. Проходя мимо искалеченного тела мурлока, я заметил странную затверделую опухоль, выступающую из раны. Начав изучать опухоль, я понял, что она имеет свойства, схожие с собираемым мной мхом. К несчастью, других опухолей, кроме этой, я не нашёл.', 0),
(247, 'ruRU', 'Следующие несколько недель я провёл, переезжая с места на место, никогда не задерживаясь из страха перед Всадниками. Сейчас я в заброшенном городе Вороний Холм, как всегда, прячусь. Я не могу противостоять той силе, что они применили против жены Свена, и знаю, что она до сих пор ищет по Сумеречному лесу Серп. Он утерян для меня, и я благодарю Свет за это, ибо, если бы я сохранил его, знаю, меня бы нашли. Даже сейчас я чувствую в сердце, что буду найден. Я так устал.', 0),
(260, 'ruRU', 'И когда это будет сделано, может начаться следующий этап нашего плана. С собственной державой и опорой силы в этом регионе мы сможем подготовить путь для Третьего Легиона. Скоро Лорды Легиона наградят наши труды, снова обрушив огонь с небес!', 0),
(305, 'ruRU', 'Приказы Кровавого Паруса Слушайте внимательно эти слова, морячки, ведь у нас только один шанс на Пиратскую Бухту. Я отправил старину Дункена разведать к северу и велел ему ждать сигнала. «Удача Дамочки» бросит якорь у южного мыса для нужд поставки. Капитан Стилуотер, этот коротышка, пусть готовит команду тащить наверх всю награбленную добычу. Уверен, Брут, этот тупица, будет на чеку.', 0),
(325, 'ruRU', 'Кракены взревели, и их голоса громыхали, как океанский шторм:$B$B«Мы идём».$B$BМин''лот, стоя твёрдо, воззвал к своей магии. Волны, посланные к И''лалии, раздвинулись и омыли оба берега, затопив джунгли за ними. Тогда Мин''лот велел своим приближённым петь заклинания связывания, и поднялся гул сотен троллийских голосов.$B$BИ один голос поднялся выше остальных.', 0),
(326, 'ruRU', 'Мин''лот взревел, и его магия собрала силу заклинаний его прислужников, и он обрушил её на приближающихся Кракенов.$B$BМоря раздвинулись, и заклинание Мин''лота устремилось к слугам Нептулона. Молния разорвала небо, и заклинание поразило их, и тысячи разрядов упали, вскипая воду и выжигая кратеры в земле.$B$BМин''лот вскричал от торжества, зная, что его заклинание свалит великих тварей.', 0),
(327, 'ruRU', 'Но Кракены стары, очень стары. Они помнили, когда земля впервые родилась из моря.$B$BОни помнили, когда правили Древние и когда пришли Путешественники и низвергли их. Они помнили, когда магия была нова.$B$BОни стары и хранят множество тайн. И хотя заклинание Мин''лота было сильным, оно, как и тролль, было смертным.$B$BИ потому оно не сработало.', 0),
(328, 'ruRU', 'Оно не смогло связать Кракенов, но разъярило их. Не за эоны смертный причинял им боль, а заклинание тролля было болезненным.$B$BИ потому они сбросили путы заклинания Мин''лота, но затем взревели и ударили с яростью.$B$BРаздался гул, когда огромные волны поднялись из глубин и устремились к земле. Когда они достигли И''лалаи, они отбросили тень на город.$B$BНо прежде чем уничтожить его, Кракены замерли, готовые.', 0),
(329, 'ruRU', 'Троллийские знахари дрожали и кричали своему повелителю. Мин''лот взглянул на горы моря, обречённые и непокорные. Он обратился к своим адептам и прошептал, и тролли вырезали его последние слова на камне. Мин''лот тогда посмотрел на нависающих Кракенов.$B$BОн скривился и метнул свой посох, свой последний смелый поступок.$B$BКракены тогда обратили свою ярость на Мин''лота, и океан обрушился на И''лалаи.$B$BИ его не стало.', 0),
(330, 'ruRU', 'И тогда воды обрушились на джунгли, смывая всё, что встречали. Тролли и звери кричали, когда воды разбивали и топили их.$B$BМногие гурубаши удивлялись, почему океан поглотил их, но затем они умерли и больше ничего не знали.$B$BИ наконец, когда воды достигли гор, они остановились. Умиротворённые, они отступили обратно за берега, оставив за собой след смерти.$B$BОни отступили, но окружили И''лалаи и остались, затопив его навеки.', 0),
(331, 'ruRU', 'А вождь Вар''газул, в безопасности за горами Зул''Гуруба, вышел в джунгли и обнаружил их смытыми от его народа.$B$BИ он впал в отчаяние, ибо его мечты о завоевании были разрушены.$B$BИ никогда не был найден Мин''лот Змей.', 0),
(332, 'ruRU', 'Но о, Сара, если мёртвые могут возвращаться в Азерот и невидимо витать рядом с теми, кого любят, я всегда буду рядом с тобой — в самый радостный день и в самую тёмную ночь, среди твоих счастливейших моментов и мрачнейших часов, всегда, всегда, и если лёгкий ветерок коснётся твоих щёк, это будет моё дыхание, а когда прохладный воздух овеет твой пульсирующий висок, это будет мой дух, пролетающий рядом.$B$BСара, не скорби по мне, мёртвому, думай, что я ушёл, и жди меня, ибо мы встретимся снова.$B$B--Салли', 0),
(335, 'ruRU', 'Не место скромной жене солдата задавать такие вопросы.$B$BИ всё же я пишу тебе теперь как скромная вдова солдата. Мой муж был для тебя лишь одним солдатом среди тысяч. Для меня он был великим Салли Баллу, отцом моих детей и моим единственным спутником в этой жизни.$B$BПрости меня, если мои вопросы к тебе, о великий вождь, звучат неуместно. Но мёртвые не могут задать эти вопросы сами....$B$BТвоя верная подданная,$BСара Баллу', 0);
